import{_ as s,o as e,c as a,a5 as o}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"하단 LED — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/led-bottom.md","filePath":"ko/software/sdk/cpp/led-bottom.md","lastUpdated":1792759058000}'),i={name:"ko/software/sdk/cpp/led-bottom.md"};function d(n,t,l,c,p,r){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="하단-led-—-c-예제" tabindex="-1">하단 LED — C++ 예제 <a class="header-anchor" href="#하단-led-—-c-예제" aria-label="Permalink to &quot;하단 LED — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq/rbq_led_bottom.cpp</code></p><p>몸통 아래의 <strong>상태 LED 두 개</strong>(오른쪽·왼쪽)를 설정하고, 로봇이 알려 주는 상태를 출력하는 예제입니다. <code>rt/rbq/cmd/led_bottom</code>에 <code>LedBottom</code> 메시지를 한 번 발행하고, <code>rt/rbq/led_bottom</code>의 1 Hz <code>LedBottomState</code>를 기다려 출력한 뒤 종료합니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><ol><li>명령행에서 <code>interface</code>와 선택 인자 <code>side mode r g b on_ms off_ms count</code>를 읽습니다.</li><li>해당 인터페이스로 DDS <code>ChannelFactory</code>를 초기화하고 <code>rt/rbq/cmd/led_bottom</code>에 <code>Publisher&lt;LedBottom_&gt;</code>, <code>rt/rbq/led_bottom</code>에 <code>Subscriber&lt;LedBottomState_&gt;</code>를 만듭니다.</li><li>DDS 디스커버리를 ~500 ms 기다린 뒤 <code>LedBottom</code> 필드를 채워 <strong>한 번</strong> 발행합니다.</li><li>IF 보드가 설정을 적용하고 알려 줄 때까지 ~2.5 초 기다린 뒤, 마지막으로 받은 <code>LedBottomState</code>를 출력하고 종료합니다.</li></ol><p>로봇의 <strong>Network</strong> 프로세스가 명령을 받아 범위를 검사하고(<code>PUT /api/led/bottom</code>과 같은 검사) Motion 에 넘기면, Motion 이 CAN FD 로 IF 보드에 보냅니다. 설정은 IF 보드가 쥐고 있으며 1 초마다 알려 주고, Network 가 그 값을 <code>rt/rbq/led_bottom</code>으로 다시 발행합니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>로봇 스택이 실행 중이며 동일 DDS 인터페이스에서 접근 가능해야 합니다.</li><li><strong>CAN FD 기체.</strong> 다른 기체에서는 Network 가 명령을 거부하고 상태도 발행하지 않아 예제가 <code>no state on rt/rbq/led_bottom</code>을 출력합니다. 시뮬레이터에서는 Motion 이 IF 보드 역할을 대신하고 MuJoCo 가 몸통 밑 LED 두 개를 보여 주므로 예제가 그대로 동작합니다.</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리 위치: <code>bin/rbq_led_bottom</code></p><h2 id="run" tabindex="-1">실행 <a class="header-anchor" href="#run" aria-label="Permalink to &quot;실행 {#run}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [interface] [side] [mode] [r] [g] [b] [on_ms] [off_ms] [count]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 양쪽 파랑으로 켜 두기(기본값) — 인터페이스가 항상 먼저 옵니다:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 오른쪽을 빨강으로 0.5 초 켜고 0.5 초 끄기를 계속:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> right</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blink</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 255</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 양쪽 끄기:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_led_bottom</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> both</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span></code></pre></div><p>인자는 모두 위치 인자이므로 <strong>인터페이스를 첫 인자로 넘겨야 합니다</strong>. 로봇에 닿는 인터페이스를 쓰세요 — 로봇 PC 에서 돌리면 <code>lo</code>, 다른 호스트에서는 본인 NIC.</p><table tabindex="0"><thead><tr><th>인자</th><th>의미</th><th>기본값</th></tr></thead><tbody><tr><td><code>interface</code></td><td>CycloneDDS 인터페이스 (로봇 PC <code>lo</code> / 다른 호스트 NIC)</td><td>—</td></tr><tr><td><code>side</code></td><td><code>right</code> / <code>left</code> / <code>both</code> — 고르지 않은 쪽은 그대로</td><td><code>both</code></td></tr><tr><td><code>mode</code></td><td><code>off</code> / <code>on</code> / <code>blink</code></td><td><code>on</code></td></tr><tr><td><code>r g b</code></td><td>색, 각 0~255</td><td><code>0 0 255</code></td></tr><tr><td><code>on_ms off_ms</code></td><td>깜빡일 때 켜는·끄는 시간, 10~2550 ms(10 ms 단위); <code>blink</code>가 아니면 무시</td><td><code>500 500</code></td></tr><tr><td><code>count</code></td><td>깜빡이는 횟수, <code>0</code> = 계속; <code>blink</code>가 아니면 무시</td><td><code>0</code></td></tr></tbody></table><p>범위 밖 값은 Network 가 거부하고(로봇 로그에 남음) LED 는 그대로 있습니다.</p><h2 id="출력-예시" tabindex="-1">출력 예시 <a class="header-anchor" href="#출력-예시" aria-label="Permalink to &quot;출력 예시&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_led_bottom] published: side=right mode=blink rgb=255,0,0 on_ms=500 off_ms=500 count=0</span></span>
<span class="line"><span>[rbq_led_bottom] state: age_ms=312 configured=1 if_fw=2026100701</span></span>
<span class="line"><span>  right: mode=blink rgb=255,0,0 on_ms=500 off_ms=500 count=0 actual=255,0,0 lpf_w=0.6</span></span>
<span class="line"><span>  left: mode=on rgb=0,0,255 on_ms=0 off_ms=0 count=0 actual=0,0,255 lpf_w=0.4</span></span></code></pre></div><p>값은 로봇마다 다릅니다. <code>actual</code>은 IF 보드의 전력 제한을 거친 마지막 출력이고, 최근 1 초 안에 그 제한이 출력을 줄였으면 <code>limited</code>가 붙습니다. <code>configured=0</code>은 IF 보드가 재부팅해 설정이 없다는 뜻이며, Motion 이 마지막 설정을 스스로 다시 보냅니다.</p>`,20)])])}const b=s(i,[["render",d]]);export{k as __pageData,b as default};
